-- Scheme directory refreshed from official sources on 2026-10-09.
-- No universal enrollment deadline was verified: NULL means consult the official portal, not enrollment open.
-- Updates only the five named legacy scheme records; preserves IDs and unrelated records.
START TRANSACTION;
INSERT INTO TblGovernmentScheme (SchemeName, Description, Eligibility, Category, DocumentUrl, Status, IsActive, CreatedDate) SELECT 'PM-KISAN', 'Income support of Rs. 6,000 per year in three instalments for eligible landholding farmer families. Use the official portal for registration, e-KYC and beneficiary status.', 'Eligible landholding farmer families, subject to official exclusion criteria and verification. Check land records, Aadhaar/e-KYC and bank details with the official service.', 'Subsidy', 'https://pmkisan.gov.in/', 'Active', 1, NOW() WHERE NOT EXISTS (SELECT 1 FROM TblGovernmentScheme WHERE SchemeName='PM-KISAN');
UPDATE TblGovernmentScheme SET Description='Income support of Rs. 6,000 per year in three instalments for eligible landholding farmer families. Use the official portal for registration, e-KYC and beneficiary status.', Eligibility='Eligible landholding farmer families, subject to official exclusion criteria and verification. Check land records, Aadhaar/e-KYC and bank details with the official service.', Category='Subsidy', DocumentUrl='https://pmkisan.gov.in/', Status='Active', IsActive=1, LastDate=NULL, UpdatedDate=NOW() WHERE SchemeName='PM-KISAN';
INSERT INTO TblGovernmentScheme (SchemeName, Description, Eligibility, Category, DocumentUrl, Status, IsActive, CreatedDate) SELECT 'Soil Health Card Scheme', 'Soil testing and a card describing nutrient status and soil-based recommendations. Contact the local agriculture office or soil testing laboratory for sample collection and card access.', 'Farmers seeking soil analysis. Sample collection, laboratory access and local implementation must be confirmed with the agriculture department.', 'Training', 'https://soilhealth.dac.gov.in/', 'Active', 1, NOW() WHERE NOT EXISTS (SELECT 1 FROM TblGovernmentScheme WHERE SchemeName='Soil Health Card Scheme');
UPDATE TblGovernmentScheme SET Description='Soil testing and a card describing nutrient status and soil-based recommendations. Contact the local agriculture office or soil testing laboratory for sample collection and card access.', Eligibility='Farmers seeking soil analysis. Sample collection, laboratory access and local implementation must be confirmed with the agriculture department.', Category='Training', DocumentUrl='https://soilhealth.dac.gov.in/', Status='Active', IsActive=1, LastDate=NULL, UpdatedDate=NOW() WHERE SchemeName='Soil Health Card Scheme';
INSERT INTO TblGovernmentScheme (SchemeName, Description, Eligibility, Category, DocumentUrl, Status, IsActive, CreatedDate) SELECT 'Kisan Credit Card', 'Bank credit for cultivation, post-harvest needs and eligible agriculture-related activities. Apply through a participating bank; loan limits, interest and approval depend on applicable bank rules.', 'Owner cultivators, eligible tenant farmers, oral lessees, sharecroppers and farmer SHGs/JLGs, subject to bank assessment and documentation.', 'Loan', 'https://www.myscheme.gov.in/schemes/kcc', 'Active', 1, NOW() WHERE NOT EXISTS (SELECT 1 FROM TblGovernmentScheme WHERE SchemeName='Kisan Credit Card');
UPDATE TblGovernmentScheme SET Description='Bank credit for cultivation, post-harvest needs and eligible agriculture-related activities. Apply through a participating bank; loan limits, interest and approval depend on applicable bank rules.', Eligibility='Owner cultivators, eligible tenant farmers, oral lessees, sharecroppers and farmer SHGs/JLGs, subject to bank assessment and documentation.', Category='Loan', DocumentUrl='https://www.myscheme.gov.in/schemes/kcc', Status='Active', IsActive=1, LastDate=NULL, UpdatedDate=NOW() WHERE SchemeName='Kisan Credit Card';
INSERT INTO TblGovernmentScheme (SchemeName, Description, Eligibility, Category, DocumentUrl, Status, IsActive, CreatedDate) SELECT 'Crop Insurance (PMFBY)', 'Crop insurance for notified crops and areas against covered risks. Enrollment dates and availability depend on the state, district, crop and season; verify current notifications before applying.', 'Farmers cultivating a notified crop in a notified area, subject to the current season notification and required documents. This listing does not confirm availability in Gujarat.', 'Insurance', 'https://pmfby.gov.in/home', 'Active', 1, NOW() WHERE NOT EXISTS (SELECT 1 FROM TblGovernmentScheme WHERE SchemeName='Crop Insurance (PMFBY)');
UPDATE TblGovernmentScheme SET Description='Crop insurance for notified crops and areas against covered risks. Enrollment dates and availability depend on the state, district, crop and season; verify current notifications before applying.', Eligibility='Farmers cultivating a notified crop in a notified area, subject to the current season notification and required documents. This listing does not confirm availability in Gujarat.', Category='Insurance', DocumentUrl='https://pmfby.gov.in/home', Status='Active', IsActive=1, LastDate=NULL, UpdatedDate=NOW() WHERE SchemeName='Crop Insurance (PMFBY)';
INSERT INTO TblGovernmentScheme (SchemeName, Description, Eligibility, Category, DocumentUrl, Status, IsActive, CreatedDate) SELECT 'Agricultural Mechanization', 'Information on machinery assistance and access to farm mechanization services. Subsidy amounts, equipment eligibility and application windows are determined by the applicable government component and state notification.', 'Eligible applicants under the relevant machinery-assistance component. Confirm applicant category, equipment, state allocation and application window with the official portal or agriculture office.', 'Subsidy', 'https://agrimachinery.nic.in/', 'Active', 1, NOW() WHERE NOT EXISTS (SELECT 1 FROM TblGovernmentScheme WHERE SchemeName='Agricultural Mechanization');
UPDATE TblGovernmentScheme SET Description='Information on machinery assistance and access to farm mechanization services. Subsidy amounts, equipment eligibility and application windows are determined by the applicable government component and state notification.', Eligibility='Eligible applicants under the relevant machinery-assistance component. Confirm applicant category, equipment, state allocation and application window with the official portal or agriculture office.', Category='Subsidy', DocumentUrl='https://agrimachinery.nic.in/', Status='Active', IsActive=1, LastDate=NULL, UpdatedDate=NOW() WHERE SchemeName='Agricultural Mechanization';
COMMIT;
SELECT Id, SchemeName, Category, LastDate, DocumentUrl FROM TblGovernmentScheme ORDER BY Id;
